sp_widget.css:
.attendance-card {
    max-width: 650px;
    margin: 60px auto;
    padding: 40px;
    background: white;
    border-radius: 15px;
    text-align: center;
    box-shadow: 0 4px 18px rgba(0,0,0,0.15);
}

.attendance-card h1 {
    font-size: 32px;
    margin-bottom: 10px;
}

.attendance-card h2 {
    font-size: 28px;
    margin: 15px 0;
}

.attendance-card p {
    font-size: 16px;
    margin: 12px;
}

.success-box {
    padding: 25px;
    background: #e8f5e9;
    border-radius: 12px;
    color: #256029;
}

.checkmark {
    width: 70px;
    height: 70px;
    line-height: 70px;
    margin: 0 auto 15px;
    border-radius: 50%;
    background: #2e7d32;
    color: white;
    font-size: 42px;
    font-weight: bold;
}

.status {
    margin-top: 25px;
    padding: 15px;
    background: #c8e6c9;
    border-radius: 8px;
    color: #1b5e20;
}

sp_widget.script:
(function() {

    data.interview = null;
    data.success = false;
    data.error = '';

    // Get interview ID from QR URL
    var interviewId = $sp.getParameter('interview_id');

    if (!interviewId) {
        data.error = 'Interview ID is missing.';
        return;
    }

    var gr = new GlideRecord('x_snc_campus360_mock_interview');

    if (!gr.get(interviewId)) {
        data.error = 'Interview not found.';
        return;
    }

    // Mark attendance automatically when QR is scanned
    if (gr.getValue('attendance_status') != 'Present') {

        gr.setValue('attendance_status', 'Present');
        gr.setValue('qr_status', 'Scanned');
        gr.update();

    }

    // Prepare interview information
    data.interview = {
        sys_id: gr.getUniqueValue(),
        interview_id: gr.getValue('interview_id'),
        student: gr.student.getDisplayValue(),
        interview_date: gr.getDisplayValue('interview_date'),
        interview_type: gr.getDisplayValue('interview_type'),
        start_time: gr.getDisplayValue('start_time'),
        end_time: gr.getDisplayValue('end_time'),
        attendance_status: 'Present',
        qr_status: 'Scanned'
    };

    // Attendance is successful
    data.success = true;
    data.message = 'Attendance marked successfully.';

})();
